//#region src/item/query.ts
	function matchItem(item, name, compare) {
		const type = typeof name;
		if (type === "object") {
			for (const key in name) if (Object.hasOwn(name, key) && !matchItem(item, key, name[key])) return false;
			return true;
		} else if (type === "function") return name(item);
		else if (name === "match") return compare(item);
		else {
			let value = /^(empty|editable)$/.test(name) ? item["is" + capitalize(name)]() : item[name];
			if (name === "class") {
				if (typeof compare === "function") return item instanceof compare;
				value = item.className;
			}
			if (typeof compare === "function") return !!compare(value);
			else if (compare) {
				if (compare.test) return compare.test(value);
				else if (isPlainObject(compare)) return matchObject(compare, value);
			}
			return equals(value, compare);
		}
	}
	function getItems(owner, options, matrix, firstOnly) {
		const items = [];
		const obj = typeof options === "object" && options;
		const overlapping = obj && obj.overlapping;
		const inside = obj && obj.inside;
		const recursive = !obj || obj.recursive !== false;
		const bounds = overlapping || inside;
		const rect = bounds && Rectangle.from(bounds);
		const path = overlapping && Path.rectangle({
			rectangle: rect,
			insert: false
		});
		if (obj) {
			options = {};
			for (const [key, value] of Object.entries(obj)) if (value !== void 0 && !/^(recursive|inside|overlapping)$/.test(key)) options[key] = value;
		}
		const collect = (item, matrix) => {
			const transform = rect ? matrix ?? new Matrix() : null;
			for (const child of item._children ?? []) {
				const childMatrix = transform?.appended(child._matrix);
				let add = true;
				if (rect) {
					const bounds = child.getBounds(childMatrix);
					if (!rect.intersects(bounds)) continue;
					if (!(rect.contains(bounds) || overlapping && path.intersects(child, childMatrix))) add = false;
				}
				if (add && matchItem(child, options)) {
					items.push(child);
					if (firstOnly) break;
				}
				if (recursive && child.children) collect(child, childMatrix);
				if (firstOnly && items.length > 0) break;
			}
		};
		collect(owner, matrix);
		return items;
	}
	function matchObject(obj1, obj2) {
		for (const key in obj1) if (Object.hasOwn(obj1, key)) {
			const value1 = obj1[key];
			const value2 = obj2[key];
			if (isPlainObject(value1) && isPlainObject(value2)) {
				if (!matchObject(value1, value2)) return false;
			} else if (!equals(value1, value2)) return false;
		}
		return true;
	}

