//#region src/path/PathFitter.ts
/**
	* @private
	*/
	var PathFitter = class extends Base {
		#points;
		#closed;
		constructor(segments, closed) {
			super();
			const points = [];
			let previous;
			for (let i = 0, l = segments.length; i < l; i++) {
				const { point } = segments[i];
				if (!previous || !previous.equals(point)) points.push(previous = point.clone());
			}
			if (closed) {
				points.unshift(points[points.length - 1]);
				points.push(points[1]);
			}
			this.#points = points;
			this.#closed = closed;
		}
		fit(error, tangent1, tangent2) {
			const points = this.#points;
			const { length } = points;
			let segments = null;
			if (length > 0) {
				segments = [new Segment(points[0])];
				if (length > 1) {
					this.#fitCubic(segments, error, 0, length - 1, tangent1 || points[1].subtract(points[0]), tangent2 || points[length - 2].subtract(points[length - 1]));
					if (this.#closed) {
						segments.shift();
						segments.pop();
					}
				}
			}
			return segments;
		}
		#fitCubic(segments, error, first, last, tangent1, tangent2) {
			const points = this.#points;
			if (last - first === 1) {
				const point1 = points[first];
				const point2 = points[last];
				const distance = point1.getDistance(point2) / 3;
				this.#addCurve(segments, [
					point1,
					point1.add(tangent1.normalize(distance)),
					point2.add(tangent2.normalize(distance)),
					point2
				]);
				return;
			}
			const uPrime = this.#chordLengthParameterize(first, last);
			let maxError = Math.max(error, error * error);
			let split;
			let parametersInOrder = true;
			for (let i = 0; i <= 4; i++) {
				const curve = this.#generateBezier(first, last, uPrime, tangent1, tangent2);
				const max = this.#findMaxError(first, last, curve, uPrime);
				if (max.error < error && parametersInOrder) {
					this.#addCurve(segments, curve);
					return;
				}
				split = max.index;
				if (max.error >= maxError) break;
				parametersInOrder = this.#reparameterize(first, last, uPrime, curve);
				maxError = max.error;
			}
			const tangentCenter = points[split - 1].subtract(points[split + 1]);
			this.#fitCubic(segments, error, first, split, tangent1, tangentCenter);
			this.#fitCubic(segments, error, split, last, tangentCenter.negate(), tangent2);
		}
		#addCurve(segments, curve) {
			const previous = segments[segments.length - 1];
			previous.handleOut = curve[1].subtract(curve[0]);
			segments.push(new Segment(curve[3], curve[2].subtract(curve[3])));
		}
		#generateBezier(first, last, uPrime, tangent1, tangent2) {
			const { abs } = Math;
			const points = this.#points;
			const point1 = points[first];
			const point2 = points[last];
			const C = [[0, 0], [0, 0]];
			const X = [0, 0];
			for (let i = 0, l = last - first + 1; i < l; i++) {
				const u = uPrime[i];
				const t = 1 - u;
				const b = 3 * u * t;
				const b0 = t * t * t;
				const b1 = b * t;
				const b2 = b * u;
				const b3 = u * u * u;
				const a1 = tangent1.normalize(b1);
				const a2 = tangent2.normalize(b2);
				const tmp = points[first + i].subtract(point1.multiply(b0 + b1)).subtract(point2.multiply(b2 + b3));
				C[0][0] += a1.dot(a1);
				C[0][1] += a1.dot(a2);
				C[1][0] = C[0][1];
				C[1][1] += a2.dot(a2);
				X[0] += a1.dot(tmp);
				X[1] += a2.dot(tmp);
			}
			const detC0C1 = C[0][0] * C[1][1] - C[1][0] * C[0][1];
			let alpha1;
			let alpha2;
			if (abs(detC0C1) > 1e-12) {
				const detC0X = C[0][0] * X[1] - C[1][0] * X[0];
				alpha1 = (X[0] * C[1][1] - X[1] * C[0][1]) / detC0C1;
				alpha2 = detC0X / detC0C1;
			} else {
				const c0 = C[0][0] + C[0][1];
				const c1 = C[1][0] + C[1][1];
				alpha1 = alpha2 = abs(c0) > 1e-12 ? X[0] / c0 : abs(c1) > 1e-12 ? X[1] / c1 : 0;
			}
			const segmentLength = point2.getDistance(point1);
			const eps = EPSILON * segmentLength;
			let handle1;
			let handle2;
			if (alpha1 < eps || alpha2 < eps) alpha1 = alpha2 = segmentLength / 3;
			else {
				const line = point2.subtract(point1);
				handle1 = tangent1.normalize(alpha1);
				handle2 = tangent2.normalize(alpha2);
				if (handle1.dot(line) - handle2.dot(line) > segmentLength * segmentLength) {
					alpha1 = alpha2 = segmentLength / 3;
					handle1 = handle2 = null;
				}
			}
			return [
				point1,
				point1.add(handle1 || tangent1.normalize(alpha1)),
				point2.add(handle2 || tangent2.normalize(alpha2)),
				point2
			];
		}
		#reparameterize(first, last, u, curve) {
			const points = this.#points;
			for (let i = first; i <= last; i++) u[i - first] = this.#findRoot(curve, points[i], u[i - first]);
			for (let i = 1, l = u.length; i < l; i++) if (u[i] <= u[i - 1]) return false;
			return true;
		}
		#findRoot(curve, point, u) {
			const curve1 = [];
			const curve2 = [];
			for (let i = 0; i <= 2; i++) curve1[i] = curve[i + 1].subtract(curve[i]).multiply(3);
			for (let i = 0; i <= 1; i++) curve2[i] = curve1[i + 1].subtract(curve1[i]).multiply(2);
			const pt = this.#evaluate(3, curve, u);
			const pt1 = this.#evaluate(2, curve1, u);
			const pt2 = this.#evaluate(1, curve2, u);
			const diff = pt.subtract(point);
			const df = pt1.dot(pt1) + diff.dot(pt2);
			return isMachineZero(df) ? u : u - diff.dot(pt1) / df;
		}
		#evaluate(degree, curve, t) {
			const tmp = curve.slice();
			for (let i = 1; i <= degree; i++) for (let j = 0; j <= degree - i; j++) tmp[j] = tmp[j].multiply(1 - t).add(tmp[j + 1].multiply(t));
			return tmp[0];
		}
		#chordLengthParameterize(first, last) {
			const points = this.#points;
			const u = [0];
			for (let i = first + 1; i <= last; i++) u[i - first] = u[i - first - 1] + points[i].getDistance(points[i - 1]);
			for (let i = 1, m = last - first; i <= m; i++) u[i] /= u[m];
			return u;
		}
		#findMaxError(first, last, curve, u) {
			const points = this.#points;
			let index = Math.floor((last - first + 1) / 2);
			let maxDistance = 0;
			for (let i = first + 1; i < last; i++) {
				const v = this.#evaluate(3, curve, u[i - first]).subtract(points[i]);
				const distance = v.x * v.x + v.y * v.y;
				if (distance >= maxDistance) {
					maxDistance = distance;
					index = i;
				}
			}
			return {
				error: maxDistance,
				index
			};
		}
	};

